<span class="line"><span style="color:#8FD0F2;">export</span><span style="color:#8FD0F2;"> const</span><span style="color:#DCE9F2;"> NOTE_READ = </span><span style="color:#E7C58C;">&#39;note_read&#39;</span><span style="color:#DCE9F2;">;</span></span>
